export const css: string = "/*\n * Tempra design tokens: the one place values live (TEMPRA-8). Deliberately plain for now, close to\n * browser defaults; the design pass (TEMPRA-1) changes values here and both the app and the site\n * follow. Light and dark come from the user's system through light-dark().\n */\n:root {\n  color-scheme: light dark;\n\n  /* Color */\n  --tempra-color-text: light-dark(#111111, #e8e8e8);\n  --tempra-color-muted: light-dark(#555555, #a8a8a8);\n  --tempra-color-bg: light-dark(#ffffff, #121212);\n  --tempra-color-link: light-dark(#0000ee, #8ab4f8);\n  --tempra-color-link-visited: light-dark(#551a8b, #c58af9);\n  --tempra-color-border: light-dark(#cccccc, #444444);\n  --tempra-color-code-bg: light-dark(#f4f4f4, #1e1e1e);\n\n  /* Type */\n  --tempra-font-body: system-ui, sans-serif;\n  --tempra-font-mono: ui-monospace, monospace;\n  --tempra-font-size: 1rem;\n  --tempra-line-height: 1.5;\n  --tempra-measure: 70ch;\n\n  /* Space */\n  --tempra-space-1: 0.25rem;\n  --tempra-space-2: 0.5rem;\n  --tempra-space-3: 1rem;\n  --tempra-space-4: 2rem;\n\n  /* Shape */\n  --tempra-radius: 0;\n}\n\n/* Element defaults for every page of the app and the site; values come from tokens.css. */\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  padding: var(--tempra-space-3);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-font-size);\n  line-height: var(--tempra-line-height);\n}\n\na {\n  color: var(--tempra-color-link);\n}\n\na:visited {\n  color: var(--tempra-color-link-visited);\n}\n\ncode,\npre,\nkbd,\nsamp {\n  font-family: var(--tempra-font-mono);\n}\n\nhr {\n  border: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\ntable {\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  padding: var(--tempra-space-1) var(--tempra-space-2);\n  text-align: left;\n  vertical-align: top;\n}\n\nimg {\n  max-width: 100%;\n}\n\n/* A row of short labels (type, trust tier, status): kept apart, wrapping on narrow screens. */\n.chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--tempra-space-1) var(--tempra-space-2);\n}\n\n/* Text for screen readers only: what a symbol (a mark, an icon) means. */\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n/*\n * How a rendered concept reads: the markdown body of a concept, in the app now and wherever\n * concepts are shown later (the site, inline MCP Apps views). Scoped to .prose.\n */\n.prose {\n  max-width: var(--tempra-measure);\n}\n\n.prose pre {\n  overflow-x: auto;\n  padding: var(--tempra-space-2);\n  background: var(--tempra-color-code-bg);\n  border-radius: var(--tempra-radius);\n}\n\n.prose blockquote {\n  margin-left: 0;\n  padding-left: var(--tempra-space-3);\n  border-left: 3px solid var(--tempra-color-border);\n  color: var(--tempra-color-muted);\n}\n\n.prose table th,\n.prose table td {\n  border: 1px solid var(--tempra-color-border);\n}\n\n.prose .footnotes {\n  font-size: 0.9em;\n  color: var(--tempra-color-muted);\n}\n\n/*\n * The concept reader (Wordgard, TEMPRA-11). Wordgard themes itself through --wg-* variables set\n * on its own element; these map them to Tempra's tokens and keep the body as plain as the rest of\n * the page. The selectors are one step more specific than Wordgard's injected theme.\n */\ndiv.body > * {\n  --wg-panel-color: var(--tempra-color-bg);\n  --wg-border-color: var(--tempra-color-border);\n  --wg-highlight-color: var(--tempra-color-text);\n  --wg-menu-color: var(--tempra-color-text);\n  --wg-dialog-font: inherit;\n  border: 0;\n}\n\ndiv.body wg-content {\n  padding: 0;\n  /* Without padding, the first block's top margin would collapse through the content's edge, and\n     Wordgard (which draws the caret from the scroller's top but measures it from the content's)\n     would draw every caret that much too high. A block formatting context keeps it inside. */\n  display: flow-root;\n}\n\n.tooltip {\n  max-width: 32rem;\n  padding: var(--tempra-space-1) var(--tempra-space-2);\n  border: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n}\n\n.prose a.broken {\n  text-decoration-line: line-through;\n}\n\n.prose pre.raw,\n.prose code.raw {\n  color: var(--tempra-color-muted);\n}\n\n.toc {\n  padding-left: var(--tempra-space-3);\n}\n\n.toc .depth-1 {\n  margin-left: var(--tempra-space-3);\n}\n\n.toc .depth-2 {\n  margin-left: var(--tempra-space-4);\n}\n\n/*\n * Comments (TEMPRA-13), in lines only: a thread's quote is underlined in the body (solid when its\n * thread is the one in focus), a comment being written is outlined, and the selection toolbar\n * and the threads are boxes and rules in the text color.\n */\nmark.comment-mark {\n  background: none;\n  color: inherit;\n  text-decoration: underline dotted;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 0.2em;\n  cursor: pointer;\n}\n\nmark.comment-mark.active {\n  text-decoration-style: solid;\n  text-decoration-thickness: 2px;\n}\n\nmark.comment-draft {\n  background: none;\n  color: inherit;\n  outline: 1px dashed var(--tempra-color-text);\n}\n\n.selection-tools {\n  display: flex;\n  gap: var(--tempra-space-1);\n  padding: var(--tempra-space-1);\n  border: 1px solid var(--tempra-color-text);\n  background: var(--tempra-color-bg);\n}\n\n.threads {\n  list-style: none;\n  padding: 0;\n}\n\n.thread {\n  border-top: 1px solid var(--tempra-color-border);\n  padding: var(--tempra-space-2) 0;\n}\n\n.thread.active {\n  outline: 1px solid var(--tempra-color-text);\n  outline-offset: 2px;\n}\n\n.quote {\n  margin: 0 0 var(--tempra-space-1);\n  color: var(--tempra-color-muted);\n  font-style: italic;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.comment {\n  margin: var(--tempra-space-1) 0;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.comment-form textarea {\n  display: block;\n  width: 100%;\n  box-sizing: border-box;\n  min-height: 3.5rem;\n  margin-bottom: var(--tempra-space-1);\n  font: inherit;\n}\n\n/*\n * The editor (TEMPRA-15), lines only like the rest: the frontmatter as a plain form, the note and\n * save bar, and the merge view's choices boxed in rules. Wordgard's menu bar and dialogs take\n * their look from the --wg-* variables above.\n */\n.edit-bar {\n  margin: var(--tempra-space-3) 0;\n  padding: var(--tempra-space-2) 0;\n  border-top: 1px solid var(--tempra-color-text);\n  border-bottom: 1px solid var(--tempra-color-text);\n}\n\n.frontmatter-form {\n  display: grid;\n  gap: var(--tempra-space-2);\n  margin: 0 0 var(--tempra-space-2);\n  padding: 0;\n  border: 0;\n}\n\n.frontmatter-form legend {\n  font-weight: bold;\n  margin-bottom: var(--tempra-space-1);\n}\n\n.frontmatter-form label {\n  display: grid;\n  gap: var(--tempra-space-1);\n}\n\n.frontmatter-form input,\n.frontmatter-form select,\n.edit-actions input {\n  font: inherit;\n  box-sizing: border-box;\n  max-width: 100%;\n}\n\n.source-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--tempra-space-1);\n  margin: var(--tempra-space-1) 0;\n}\n\n.edit-actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-2);\n}\n\n.edit-actions label {\n  flex: 1 1 20rem;\n  display: flex;\n  gap: var(--tempra-space-1);\n  align-items: center;\n}\n\n.edit-actions input {\n  flex: 1;\n}\n\n.merge {\n  margin: var(--tempra-space-3) 0;\n  padding: var(--tempra-space-2) 0;\n  border-top: 1px solid var(--tempra-color-text);\n  border-bottom: 1px solid var(--tempra-color-text);\n}\n\n.merge .conflict {\n  margin: var(--tempra-space-2) 0;\n  border: 1px solid var(--tempra-color-border);\n}\n\n.merge .conflict label {\n  display: block;\n  margin: var(--tempra-space-1) 0;\n}\n\n.merge-side {\n  margin: var(--tempra-space-1) 0 0;\n  padding: var(--tempra-space-1);\n  border: 1px solid var(--tempra-color-border);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  font-family: var(--tempra-font-mono);\n}\n\n/* The concept as stored (the page's Markdown view): the file's own text, wrapped. */\n.raw-markdown pre {\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  padding: var(--tempra-space-2);\n  border: 1px solid var(--tempra-color-border);\n}\n\n/*\n * The workspace (TEMPRA-19): a library's tree on the left, the open file in the middle, its\n * context on the right, under one header. Structure only: lines and spacing from the tokens, no\n * decoration (the UI rule). Under 60rem the side panels become drawers over the main pane.\n */\nbody:has(> #root > .workspace) {\n  padding: 0;\n}\n\n.workspace {\n  display: grid;\n  grid-template-columns: 16rem minmax(0, 1fr) 20rem;\n  grid-template-rows: auto minmax(0, 1fr);\n  grid-template-areas:\n    \"header header header\"\n    \"sidebar main context\";\n  height: 100dvh;\n}\n\n.workspace.no-context {\n  grid-template-columns: 16rem minmax(0, 1fr);\n  grid-template-areas:\n    \"header header\"\n    \"sidebar main\";\n}\n\n.ws-header {\n  grid-area: header;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-2) var(--tempra-space-3);\n  padding: var(--tempra-space-2) var(--tempra-space-3);\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\n.ws-header .ws-spacer {\n  flex: 1;\n}\n\n.ws-sidebar,\n.ws-main,\n.ws-context {\n  overflow: auto;\n  padding: var(--tempra-space-3);\n}\n\n.ws-sidebar {\n  grid-area: sidebar;\n  border-right: 1px solid var(--tempra-color-border);\n}\n\n.ws-main {\n  grid-area: main;\n}\n\n.ws-context {\n  grid-area: context;\n  border-left: 1px solid var(--tempra-color-border);\n}\n\n.ws-context h2 {\n  font-size: 1rem;\n}\n\n.ws-filter {\n  width: 100%;\n  margin-bottom: var(--tempra-space-2);\n}\n\n/* The tree: nested lists, one row per directory or file. */\n.tree,\n.tree ul,\n.ws-views {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n.tree ul {\n  padding-left: var(--tempra-space-3);\n}\n\n.tree-row {\n  display: flex;\n  align-items: baseline;\n  gap: var(--tempra-space-1);\n  white-space: nowrap;\n}\n\n.tree-row > a {\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.tree-row [aria-current=\"page\"],\n.ws-views [aria-current=\"page\"] {\n  font-weight: bold;\n}\n\n.tree-toggle {\n  flex: none;\n  width: 1.25em;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: inherit;\n  font: inherit;\n  cursor: pointer;\n}\n\n.tree-leaf {\n  flex: none;\n  width: 1.25em;\n}\n\n/* A file an agent changed in the last few minutes, or since the last visit. */\n.tree-mark {\n  flex: none;\n  color: var(--tempra-color-link);\n}\n\n.ws-views {\n  margin-top: var(--tempra-space-3);\n  padding-top: var(--tempra-space-2);\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n.ws-toggle {\n  display: none;\n}\n\n/* The quick switcher: a modal dialog with a search box and a list of files. */\n.switcher {\n  width: min(36rem, 90vw);\n  padding: var(--tempra-space-3);\n  border: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n}\n\n.switcher::backdrop {\n  background: rgb(0 0 0 / 0.3);\n}\n\n.switcher-head {\n  display: flex;\n  gap: var(--tempra-space-2);\n}\n\n.switcher-head input {\n  flex: 1;\n  min-width: 0;\n}\n\n.switcher [role=\"listbox\"] {\n  margin-top: var(--tempra-space-2);\n}\n\n.switcher [role=\"option\"] {\n  padding: var(--tempra-space-1) var(--tempra-space-2);\n  cursor: pointer;\n}\n\n.switcher [role=\"option\"][aria-selected=\"true\"] {\n  background: var(--tempra-color-code-bg);\n}\n\n@media (max-width: 60rem) {\n  .workspace,\n  .workspace.no-context {\n    grid-template-columns: minmax(0, 1fr);\n    grid-template-areas:\n      \"header\"\n      \"main\";\n  }\n\n  /* Drawers open over the main pane, below the header, so its buttons stay in reach. */\n  .ws-sidebar,\n  .ws-context {\n    grid-area: main;\n    z-index: 1;\n    display: none;\n    width: min(20rem, 85vw);\n    background: var(--tempra-color-bg);\n  }\n\n  .ws-sidebar {\n    justify-self: start;\n  }\n\n  .ws-context {\n    justify-self: end;\n  }\n\n  .ws-sidebar.open,\n  .ws-context.open {\n    display: block;\n  }\n\n  .ws-toggle {\n    display: inline-block;\n  }\n}\n";

